SELECT COUNT(*) AS total_claims
FROM claims
WHERE LEFT(GEOID, 2) = '48';

SELECT MIN(dateOfLoss) AS earliest_claim_date
FROM claims
WHERE GEOID LIKE '12%';

SELECT COUNT(*) 
FROM svi 
WHERE GEOID LIKE '48%';

SELECT COUNT(*) 
FROM zcta 
WHERE STATEFP = '22';

SELECT MIN(LON) AS westernmost_longitude
FROM schools
WHERE STATEFP = '48';

SELECT COUNT(DISTINCT CITY) 
FROM hospitals 
WHERE STATEFP = '22' AND CITY IS NOT NULL;

SELECT AVG(CAST(POPUNI AS DOUBLE)) AS average_population_universe
FROM cre
WHERE GEOID LIKE '22%';

SELECT MAX(LAT) AS northernmost_latitude
FROM hospitals
WHERE STATEFP = '12';

SELECT AVG(ST_Area(geometry)) AS average_area
FROM census_tracts
WHERE ST_IsValid(geometry);

SELECT AVG(CAST(amountPaidOnBuildingClaim AS DOUBLE)) AS avg_building_payout
FROM claims
WHERE amountPaidOnBuildingClaim IS NOT NULL;

SELECT COUNT(DISTINCT h.COUNTYFIPS) AS county_count
FROM hospitals h
WHERE h.STATEFP = '22';
